CREATE TABLE users(id uuid PRIMARY KEY,email text NOT NULL,password_hash text NOT NULL,display_name text NOT NULL,role text NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','ADMIN')),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','DISABLED')),email_verified boolean NOT NULL DEFAULT false,quota_bytes bigint NOT NULL CHECK(quota_bytes>0),used_bytes bigint NOT NULL DEFAULT 0 CHECK(used_bytes>=0),reserved_bytes bigint NOT NULL DEFAULT 0 CHECK(reserved_bytes>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_email_unique ON users(lower(email));
CREATE TABLE web_sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE account_tokens(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL CHECK(purpose IN ('VERIFY','RESET')),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz);
CREATE TABLE resources(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('MODEL','MOTION','EXPRESSION','IMAGE','ANIMATION')),name text NOT NULL,description text NOT NULL DEFAULT '',author text NOT NULL DEFAULT '',license text NOT NULL DEFAULT '',source text NOT NULL DEFAULT '',tags jsonb NOT NULL DEFAULT '[]',visibility text NOT NULL DEFAULT 'PRIVATE' CHECK(visibility IN ('PRIVATE','PUBLIC')),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','HIDDEN','DISABLED')),current_version_id uuid,cover_key text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resource_versions(id uuid PRIMARY KEY,resource_id uuid NOT NULL REFERENCES resources(id),version text NOT NULL,entrypoint text NOT NULL DEFAULT '',validation_status text NOT NULL DEFAULT 'PENDING' CHECK(validation_status IN ('PENDING','VALIDATING','READY','FAILED')),compatibility_status text NOT NULL DEFAULT 'UNTESTED' CHECK(compatibility_status IN ('UNTESTED','COMPATIBLE','INCOMPATIBLE')),minimum_client_version text NOT NULL DEFAULT '',package_key text NOT NULL DEFAULT '',package_bytes bigint NOT NULL DEFAULT 0,package_sha256 text NOT NULL DEFAULT '',validation_report jsonb NOT NULL DEFAULT '{"errors":[],"warnings":[]}',manifest jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(resource_id,version),UNIQUE(resource_id,id));
ALTER TABLE resources ADD CONSTRAINT current_version_owner FOREIGN KEY(id,current_version_id) REFERENCES resource_versions(resource_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE resource_dependencies(version_id uuid NOT NULL REFERENCES resource_versions(id) ON DELETE CASCADE,target_version_id uuid NOT NULL REFERENCES resource_versions(id),relation text NOT NULL DEFAULT 'TARGET_MODEL',PRIMARY KEY(version_id,target_version_id),CHECK(version_id<>target_version_id));
CREATE TABLE resource_files(version_id uuid NOT NULL REFERENCES resource_versions(id) ON DELETE CASCADE,path text NOT NULL,bytes bigint NOT NULL,sha256 text NOT NULL,PRIMARY KEY(version_id,path));
CREATE TABLE user_library(user_id uuid NOT NULL REFERENCES users(id),resource_id uuid NOT NULL REFERENCES resources(id),pinned_version_id uuid,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,resource_id),FOREIGN KEY(resource_id,pinned_version_id) REFERENCES resource_versions(resource_id,id));
CREATE TABLE uploads(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),resource_id uuid NOT NULL REFERENCES resources(id),version_id uuid REFERENCES resource_versions(id),purpose text NOT NULL CHECK(purpose IN ('VERSION','COVER')),filename text NOT NULL,expected_bytes bigint NOT NULL CHECK(expected_bytes>0),reserved_bytes bigint NOT NULL CHECK(reserved_bytes>0),object_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'CREATED' CHECK(status IN ('CREATED','UPLOADED','VALIDATING','READY','FAILED','CANCELLED','EXPIRED')),error_code text,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,settled boolean NOT NULL DEFAULT false);
CREATE TABLE jobs(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('VALIDATE','MAIL')),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','RUNNING','DONE','FAILED')),attempts integer NOT NULL DEFAULT 0,run_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_owner text,last_error text,created_at timestamptz NOT NULL DEFAULT now(),dedupe_key text UNIQUE);
CREATE INDEX jobs_pending ON jobs(run_at) WHERE status IN ('QUEUED','RUNNING');
CREATE TABLE idempotency_requests(user_id uuid NOT NULL REFERENCES users(id),key text NOT NULL,upload_id uuid NOT NULL REFERENCES uploads(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,key));
CREATE TABLE download_tickets(id uuid PRIMARY KEY,user_id uuid REFERENCES users(id),resource_id uuid NOT NULL REFERENCES resources(id),version_id uuid NOT NULL REFERENCES resource_versions(id),grant_id uuid,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL);
CREATE TABLE client_releases(id uuid PRIMARY KEY,version text NOT NULL,channel text NOT NULL CHECK(channel IN ('STABLE','BETA')),source_commit text NOT NULL,release_notes text NOT NULL DEFAULT '',published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(version,channel));
CREATE TABLE release_artifacts(id uuid PRIMARY KEY,release_id uuid NOT NULL REFERENCES client_releases(id),os text NOT NULL,arch text NOT NULL,distribution_type text NOT NULL,download_url text NOT NULL,sha256 text NOT NULL CHECK(length(sha256)=64),bytes bigint NOT NULL CHECK(bytes>0),system_requirements jsonb NOT NULL DEFAULT '[]',UNIQUE(release_id,os,arch));
CREATE TABLE audit_logs(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,target_id text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_grants(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),device_label text NOT NULL DEFAULT 'desktop-ai-pet',created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
ALTER TABLE download_tickets ADD CONSTRAINT download_grant FOREIGN KEY(grant_id) REFERENCES oauth_grants(id);
CREATE TABLE oauth_records(signature text PRIMARY KEY,kind text NOT NULL,request_id text NOT NULL,grant_id uuid NOT NULL REFERENCES oauth_grants(id),payload jsonb NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX oauth_records_request ON oauth_records(request_id);
